<?php require 'config.php';$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$w=[];$p=[];if($q){$w[]='(title LIKE ? OR excerpt LIKE ? OR content LIKE ?)';array_push($p,"%$q%","%$q%","%$q%");}if($cat){$w[]='category=?';$p[]=$cat;}$sql="SELECT * FROM articles ".($w?'WHERE '.implode(' AND ',$w):'')." ORDER BY views DESC,created_at DESC";$s=db()->prepare($sql);$s->execute($p);$rows=$s->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Articles — DeskFlow</title><link rel="stylesheet" href="assets/style.css"></head><body><nav class="top"><a class="logo" href="index.php"><span>desk</span>flow</a><div class="links"><a href="index.php">Help center</a><a class="active" href="articles.php">Articles</a><a href="track.php">My requests</a><a class="outline" href="request.php">Contact support</a><a class="admin" href="admin/login.php">Admin</a></div></nav><main class="library"><div class="libraryhead"><small>KNOWLEDGE BASE</small><h1>Everything you need to know.</h1><form class="librarysearch"><input name="q" value="<?=e($q)?>" placeholder="Search articles"><button>Search</button></form></div><div class="resultbar"><span><?=count($rows)?> articles</span><?php if($cat):?><b><?=e($cat)?></b><?php endif;?></div><div class="results"><?php foreach($rows as $a):?><a href="article.php?id=<?=$a['id']?>"><div><small><?=e($a['category'])?></small><h2><?=e($a['title'])?></h2><p><?=e($a['excerpt'])?></p><span><?=e((string)$a['views'])?> views · Read article →</span></div></a><?php endforeach;?><?php if(!$rows):?><div class="noresults">No articles matched your search.</div><?php endif;?></div></main></body></html>